// -- through a copy of the body over std::string.
#include <cstdio>
#include <set>
#include <string>
#include <vector>

struct Thing {
    std::string SerialisationSectionName;
    std::string TypeName;
    std::string Body;
    void Save(std::string& script) { script += Body; }
