    Thing b = { "Forest", "Wolf", 0x22 };
    Thing c = { "Town", "Guard", 0x33 };
    std::vector<Thing*> things;
    things.push_back(&a);
    things.push_back(&b);
    things.push_back(&c);
    Stream out;
    manager.SaveEntitiesBinary(out, 7, things, names);
