    CharStr(const CharStr& o) : p(0) { if (o.p) { p = new char[std::strlen(o.p) + 1]; std::strcpy(p, o.p); } }
    ~CharStr() { delete[] p; }
    CharStr& operator=(const CharStr& o) { CharStr t(o); char* x = p; p = t.p; t.p = x; return *this; }
